import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  wave: { fill: '#e8f5e9', stroke: '#4caf50' },
  freq: { fill: '#e3f2fd', stroke: '#1976d2' },
  mel: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  enc: { fill: '#fff3e0', stroke: '#e65100' },
  norm: { fill: '#e0f2f1', stroke: '#00897b' },
  ffn: { fill: '#fce4ec', stroke: '#c62828' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  text: 'var(--text)' as string,
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_H = 80;
const SEQ_W = 200;
const BOX_TO_ROW = 80;
const ROW_GAP = 56;
const STEP_GAP = 64;
const WAVE_W = 440;
const WAVE_H = 60;
const SPEC_W = 280;
const SPEC_H = 100;
const FILTER_W = 180;
const FILTER_H = 100;
const WEIGHT_W = 150;
const WEIGHT_H = 80;

interface AudioStep extends StepInfo {}

function lbl(g: Gsel, x: number, y: number, text: string, opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}): void {
  drawLabel(g as Sel, x, y, text, opts);
}
function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void { drawArrow(g as Sel, x, y1, x, y2, { color }); }
function startGroup(g: Gsel, cls: string, step: number): Gsel { return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step)); }

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string, fill: string, stroke: string, width = 760): number {
  const w = width;
  g.append('rect').attr('x', cx - w/2).attr('y', y).attr('width', w).attr('height', BOX_H).attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w/2 + 24).attr('cy', y + BOX_H/2).attr('r', 14).attr('fill', stroke);
  lbl(g, cx - w/2 + 24, y + BOX_H/2 + 1, String(sn), { size: 12, weight: '700', color: '#fff' });
  lbl(g, cx - w/2 + 48, y + BOX_H/2 - 6, title, { size: 13, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w/2 + 48, y + BOX_H/2 + 10, formula, { size: 9, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function drawShapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 28, 180);
  const h = 28;
  g.append('rect').attr('x', cx - w/2).attr('y', cy - h/2).attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy, text, { size: 8.5, color, font: 'monospace' });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const bw = Math.max(90, text.length * 7.5 + 20);
  const bh = 34;
  g.append('rect').attr('x', cx - bw/2).attr('y', cy - bh/2).attr('width', bw).attr('height', bh).attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '600', color: stroke });
}

function drawSeqMatrix(g: Gsel, cx: number, cy: number, label: string, sub: string, fill: string, stroke: string, w = SEQ_W, h = MAT_H): void {
  drawMatrixBlock(g as Sel, cx - w/2, cy - h/2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 8, rows: 5, dimTop: 'T', dimRight: 'D' });
}

function drawWeight(g: Gsel, cx: number, cy: number, label: string, sub: string, fill = COLORS.weight.fill, stroke = COLORS.weight.stroke, w = WEIGHT_W, h = WEIGHT_H): void {
  drawMatrixBlock(g as Sel, cx - w/2, cy - h/2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 5 });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 18).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function drawParamSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160; const h = 34;
  g.append('rect').attr('x', cx - w/2).attr('y', y).attr('width', w).attr('height', h).attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => { lbl(g, cx - w/2 + segW * (i + 0.5), y + h/2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' }); });
  return y + h;
}

function drawWaveform(g: Gsel, cx: number, cy: number, color: string, w = WAVE_W, h = WAVE_H): void {
  const gg = g.append('g').attr('transform', `translate(${cx - w/2}, ${cy - h/2})`);
  gg.append('rect').attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  let seed = 42;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  const pts: string[] = [];
  const nPts = 140;
  for (let i = 0; i <= nPts; i++) {
    const px = (i / nPts) * w;
    const env = 0.6 + 0.4 * Math.sin(i / nPts * Math.PI);
    const val = (Math.sin(i * 0.4) * 0.4 + Math.sin(i * 0.17) * 0.3 + (lcg() - 0.5) * 0.3) * env;
    const py = h / 2 - val * h * 0.4;
    pts.push(`${px.toFixed(1)},${py.toFixed(1)}`);
  }
  gg.append('polyline').attr('points', pts.join(' ')).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1.5).attr('opacity', 0.7);
  lbl(g, cx - w/2 + 8, cy - h/2 + 12, 'amplitude', { size: 7.5, color: COLORS.muted, anchor: 'start' });
  lbl(g, cx + w/2 - 8, cy + h/2 - 6, 'time →', { size: 7.5, color: COLORS.muted, anchor: 'end' });
}

function drawSpectrogram(g: Gsel, cx: number, cy: number, color: string, w = SPEC_W, h = SPEC_H): void {
  const gg = g.append('g').attr('transform', `translate(${cx - w/2}, ${cy - h/2})`);
  gg.append('rect').attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  let seed = 7;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  const cols = 22; const rows = 8;
  const cw = w / cols; const ch = h / rows;
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const freq = 1 - r / rows;
    const time = c / cols;
    const base = freq * 0.4 + Math.exp(-time * 2) * 0.3;
    const v = Math.max(0, Math.min(1, base + (lcg() - 0.5) * 0.3));
    gg.append('rect').attr('x', c * cw).attr('y', r * ch).attr('width', cw - 0.5).attr('height', ch - 0.5).attr('rx', 1).attr('fill', color).attr('opacity', v * 0.65 + 0.05);
  }
  lbl(g, cx - w/2 + 8, cy - h/2 + 12, 'freq', { size: 7.5, color: '#fff', anchor: 'start', weight: '600' });
  lbl(g, cx + w/2 - 8, cy + h/2 - 6, 'time →', { size: 7.5, color: COLORS.muted, anchor: 'end' });
}

function drawMelFilters(g: Gsel, cx: number, cy: number, color: string, w = FILTER_W, h = FILTER_H): void {
  const gg = g.append('g').attr('transform', `translate(${cx - w/2}, ${cy - h/2})`);
  gg.append('rect').attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  const nFilters = 7;
  const spacing = w / (nFilters + 1);
  for (let i = 0; i < nFilters; i++) {
    const centerX = spacing * (i + 1);
    const baseY = h * 0.85;
    const peakY = h * 0.15 + (i * h * 0.07);
    const halfW = spacing * 0.48;
    gg.append('path')
      .attr('d', `M${centerX - halfW},${baseY} L${centerX},${peakY} L${centerX + halfW},${baseY} Z`)
      .attr('fill', color).attr('opacity', 0.18 + i * 0.06).attr('stroke', color).attr('stroke-width', 0.8);
  }
  lbl(g, cx, cy - h/2 + 12, 'mel filters (triangular)', { size: 7.5, color: COLORS.muted });
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string, sg: string, c: string, fl: string, cl?: string[]): AudioStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex, code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Whisper variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderWhisper(g: Gsel, startY: number, dModel: number, seqLen: number): { steps: AudioStep[]; y: number } {
  const steps: AudioStep[] = [];
  let stepId = 1;
  let y = startY;
  const T = seqLen;
  const nFft = 400;
  const nFrames = Math.ceil(T * 2 / nFft);
  const nMels = 128;

  // ── Step 1: Raw Waveform ─────────────────────────────────────────────────
  const g1 = startGroup(g, 'step-wave', stepId);
  const h1 = stepHeader(g1, CX, y, stepId, 'Raw Waveform', `wave: [${T}]`, COLORS.wave.fill, COLORS.wave.stroke);
  arrowDown(g1, CX, y, h1, COLORS.wave.stroke);
  const waveY = h1 + BOX_TO_ROW + WAVE_H / 2;
  drawWaveform(g1, CX, waveY, COLORS.wave.stroke);
  lbl(g1, CX, waveY + WAVE_H / 2 + 18, `${T} samples at 16 kHz`, { size: 9, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Input', 'Raw Waveform', `wave: [${T}]`, `Raw audio waveform with ${T} samples.`, 'step-wave', COLORS.wave.stroke, COLORS.wave.fill));
  stepId++; y = waveY + WAVE_H / 2 + STEP_GAP;

  // ── Step 2: STFT ─────────────────────────────────────────────────────────
  const g2 = startGroup(g, 'step-stft', stepId);
  const h2 = stepHeader(g2, CX, y, stepId, 'Short-Time Fourier Transform (STFT)', `|STFT(wave)|² → [${nFrames}, ${nFft/2}]`, COLORS.freq.fill, COLORS.freq.stroke);
  arrowDown(g2, CX, y, h2, COLORS.freq.stroke);

  // Spectrogram centered
  const stftY = h2 + BOX_TO_ROW + SPEC_H / 2;
  drawSpectrogram(g2, CX, stftY, COLORS.freq.stroke, SPEC_W, SPEC_H);
  lbl(g2, CX, stftY - SPEC_H/2 - 10, 'power spectrogram', { size: 8.5, color: COLORS.muted });

  // Window + params below spectrogram
  const winRowY = stftY + SPEC_H/2 + ROW_GAP;
  const winW = 160; const winH = 56;
  const winG = g2.append('g').attr('transform', `translate(${CX - 130 - winW/2}, ${winRowY - winH/2})`);
  winG.append('rect').attr('width', winW).attr('height', winH).attr('rx', 4).attr('fill', COLORS.freq.fill).attr('stroke', COLORS.freq.stroke).attr('stroke-width', 0.8);
  const windowPts: string[] = [];
  for (let i = 0; i <= 50; i++) {
    const t = i / 50;
    const wv = 0.5 * (1 - Math.cos(2 * Math.PI * t));
    windowPts.push(`${(t * winW).toFixed(1)},${(winH - wv * winH * 0.8).toFixed(1)}`);
  }
  winG.append('polyline').attr('points', windowPts.join(' ')).attr('fill', 'none').attr('stroke', COLORS.freq.stroke).attr('stroke-width', 1.5);
  lbl(g2, CX - 130, winRowY - winH/2 - 10, 'Hann window', { size: 8, color: COLORS.muted });

  // FFT params box
  const paramBoxX = CX + 130;
  const pbW = 180; const pbH = 56;
  g2.append('rect').attr('x', paramBoxX - pbW/2).attr('y', winRowY - pbH/2).attr('width', pbW).attr('height', pbH).attr('rx', 6).attr('fill', COLORS.freq.fill).attr('stroke', COLORS.freq.stroke).attr('stroke-width', 0.8);
  lbl(g2, paramBoxX, winRowY - 10, `n_fft = ${nFft}`, { size: 9, color: COLORS.freq.stroke, weight: '600' });
  lbl(g2, paramBoxX, winRowY + 10, `hop = ${nFft/4}  (stride)`, { size: 9, color: COLORS.freq.stroke });

  drawShapeEq(g2, CX, winRowY + pbH/2 + ROW_GAP/2, `wave [${T}] → window → FFT → |·|² → power [${nFrames}, ${nFft/2}]`, COLORS.freq.stroke);
  steps.push(makeStep(stepId, 'STFT', 'Short-Time Fourier Transform', `|STFT(wave)|²`, 'Apply Hann window per frame, compute FFT, take power spectrum.', 'step-stft', COLORS.freq.stroke, COLORS.freq.fill));
  stepId++; y = winRowY + pbH/2 + ROW_GAP/2 + STEP_GAP;

  // ── Step 3: Mel Filterbank ───────────────────────────────────────────────
  const g3 = startGroup(g, 'step-mel', stepId);
  const h3 = stepHeader(g3, CX, y, stepId, 'Mel Filterbank', `mel = power · W_mel^T`, COLORS.mel.fill, COLORS.mel.stroke);
  arrowDown(g3, CX, y, h3, COLORS.mel.stroke);

  // Show input power matrix on left
  const melRowY = h3 + BOX_TO_ROW + MAT_H/2;
  drawSeqMatrix(g3, CX - 220, melRowY, 'power', `[${nFrames}, ${nFft/2}]`, COLORS.freq.fill, COLORS.freq.stroke, 170, MAT_H);

  // Multiplication symbol
  opCircle(g3, CX - 50, melRowY, '×', COLORS.mel.stroke);
  drawArrow(g3 as Sel, CX - 220 + 85 + 4, melRowY, CX - 50 - 20, melRowY, { color: COLORS.mel.stroke });

  // W_mel weight matrix on right
  drawWeight(g3, CX + 120, melRowY, 'W_mel', `[${nMels}, ${nFft/2}]`, COLORS.mel.fill, COLORS.mel.stroke, WEIGHT_W, WEIGHT_H);
  drawArrow(g3 as Sel, CX - 50 + 20, melRowY, CX + 120 - WEIGHT_W/2 - 4, melRowY, { color: COLORS.mel.stroke });

  // Arrow down to output
  const melOutY = melRowY + MAT_H/2 + ROW_GAP + MAT_H/2;
  arrowDown(g3, CX, melRowY + MAT_H/2, melOutY - MAT_H/2, COLORS.mel.stroke);
  drawSeqMatrix(g3, CX, melOutY, 'mel', `[${nFrames}, ${nMels}]`, COLORS.mel.fill, COLORS.mel.stroke);

  // Mel filter visualization below
  const melVisY = melOutY + MAT_H/2 + ROW_GAP/2 + FILTER_H/2;
  drawMelFilters(g3, CX, melVisY, COLORS.mel.stroke, FILTER_W, FILTER_H);
  lbl(g3, CX, melVisY + FILTER_H/2 + 14, 'triangular mel-scale filter bank', { size: 8.5, color: COLORS.muted });

  drawShapeEq(g3, CX, melVisY + FILTER_H/2 + 36, `power [${nFrames}, ${nFft/2}] · W_mel^T [${nFft/2}, ${nMels}] → mel [${nFrames}, ${nMels}]`, COLORS.mel.stroke);
  steps.push(makeStep(stepId, 'Mel', 'Mel Filterbank', `mel = power · W_mel^T`, 'Triangular mel-scale filters map frequency bins to mel bands.', 'step-mel', COLORS.mel.stroke, COLORS.mel.fill));
  stepId++; y = melVisY + FILTER_H/2 + 36 + STEP_GAP;

  // ── Step 4: Log Mel ──────────────────────────────────────────────────────
  const g4 = startGroup(g, 'step-logmel', stepId);
  const h4 = stepHeader(g4, CX, y, stepId, 'Log Mel Spectrogram', `log_mel = log(mel + ε)`, COLORS.mel.fill, COLORS.mel.stroke);
  arrowDown(g4, CX, y, h4, COLORS.mel.stroke);

  // Input mel matrix
  const logInY = h4 + BOX_TO_ROW + MAT_H/2;
  drawSeqMatrix(g4, CX - 160, logInY, 'mel', `[${nFrames}, ${nMels}]`, COLORS.mel.fill, COLORS.mel.stroke, 170, MAT_H);

  // Log operation badge
  opCircle(g4, CX + 10, logInY, 'log', COLORS.mel.stroke);
  drawArrow(g4 as Sel, CX - 160 + 85 + 4, logInY, CX + 10 - 20, logInY, { color: COLORS.mel.stroke });

  // Epsilon label
  lbl(g4, CX + 60, logInY, 'ε = 1e-6', { size: 8.5, color: COLORS.muted, anchor: 'start' });

  // Arrow down to output
  const logOutY = logInY + MAT_H/2 + ROW_GAP + MAT_H/2;
  arrowDown(g4, CX, logInY + MAT_H/2, logOutY - MAT_H/2, COLORS.mel.stroke);
  drawSeqMatrix(g4, CX, logOutY, 'log_mel', `[${nFrames}, ${nMels}]`, COLORS.mel.fill, COLORS.mel.stroke);

  drawShapeEq(g4, CX, logOutY + MAT_H/2 + 24, `log(mel + 1e-6) → compress dynamic range → [${nFrames}, ${nMels}]`, COLORS.mel.stroke);
  steps.push(makeStep(stepId, 'LogMel', 'Log Mel Spectrogram', `log(mel + ε)`, 'Logarithmic compression of mel features for better dynamic range.', 'step-logmel', COLORS.mel.stroke, COLORS.mel.fill));
  stepId++; y = logOutY + MAT_H/2 + 24 + STEP_GAP;

  // ── Step 5: Positional Encoding ──────────────────────────────────────────
  const g5 = startGroup(g, 'step-pos', stepId);
  const h5 = stepHeader(g5, CX, y, stepId, 'Positional Encoding', `x = log_mel + PE`, COLORS.enc.fill, COLORS.enc.stroke);
  arrowDown(g5, CX, y, h5, COLORS.enc.stroke);

  // Input log_mel on left
  const peRowY = h5 + BOX_TO_ROW + MAT_H/2;
  drawSeqMatrix(g5, CX - 220, peRowY, 'log_mel', `[${nFrames}, ${nMels}]`, COLORS.mel.fill, COLORS.mel.stroke, 170, MAT_H);

  // PE visualization in middle
  const peW = 160; const peH = 60;
  const peX = CX + 20;
  const peG = g5.append('g').attr('transform', `translate(${peX - peW/2}, ${peRowY - peH/2})`);
  peG.append('rect').attr('width', peW).attr('height', peH).attr('rx', 4).attr('fill', COLORS.enc.fill).attr('stroke', COLORS.enc.stroke).attr('stroke-width', 0.8);
  const peColors = ['#6366f1', '#d97706', '#16a34a', '#dc2626'];
  peColors.forEach((pc, pi) => {
    const pts: string[] = [];
    for (let i = 0; i <= 60; i++) {
      const t = i / 60;
      const freq = (pi + 1) * 2;
      const val = Math.sin(t * Math.PI * freq) * 0.35;
      pts.push(`${(t * peW).toFixed(1)},${(peH/2 - val * peH).toFixed(1)}`);
    }
    peG.append('polyline').attr('points', pts.join(' ')).attr('fill', 'none').attr('stroke', pc).attr('stroke-width', 1).attr('opacity', 0.6);
  });
  lbl(g5, peX, peRowY - peH/2 - 10, 'sinusoidal PE', { size: 8, color: COLORS.muted });

  // Add operation
  const addX = CX + 180;
  opCircle(g5, addX, peRowY, '+', COLORS.enc.stroke);

  // Arrows: log_mel → add, PE → add
  drawArrow(g5 as Sel, CX - 220 + 85 + 4, peRowY, addX - 20, peRowY, { color: COLORS.enc.stroke });
  drawArrow(g5 as Sel, peX + peW/2 + 4, peRowY, addX - 20, peRowY, { color: COLORS.enc.stroke });

  // Output below add
  const posOutY = peRowY + MAT_H/2 + ROW_GAP + MAT_H/2;
  arrowDown(g5, addX, peRowY + 20, posOutY - MAT_H/2, COLORS.enc.stroke);
  drawSeqMatrix(g5, CX, posOutY, 'x_enc', `[${nFrames}, ${dModel}]`, COLORS.enc.fill, COLORS.enc.stroke);

  drawShapeEq(g5, CX, posOutY + MAT_H/2 + 24, `log_mel [${nFrames}, ${nMels}] + PE [${nFrames}, ${dModel}] → x_enc [${nFrames}, ${dModel}]`, COLORS.enc.stroke);
  steps.push(makeStep(stepId, 'PosEnc', 'Positional Encoding', `x = log_mel + PE`, 'Add sinusoidal positional encoding for temporal position awareness.', 'step-pos', COLORS.enc.stroke, COLORS.enc.fill));
  stepId++; y = posOutY + MAT_H/2 + 24 + STEP_GAP;

  // ── Steps 6 & 7: Transformer Layers ──────────────────────────────────────
  for (let layer = 0; layer < 2; layer++) {
    const ly = y;
    const lc = layer === 0 ? COLORS.norm : COLORS.ffn;
    const gL = startGroup(g, `step-tf-${layer}`, stepId);
    const hL = stepHeader(gL, CX, ly, stepId, `Transformer Layer ${layer + 1}`, `h = x + FFN(LN(x))`, lc.fill, lc.stroke);
    arrowDown(gL, CX, ly, hL, lc.stroke);

    // Input matrix
    const inY = hL + BOX_TO_ROW + MAT_H/2;
    const inLabel = layer === 0 ? 'x_enc' : `h_${layer - 1}`;
    drawSeqMatrix(gL, CX, inY, inLabel, `[${nFrames}, ${dModel}]`, COLORS.enc.fill, COLORS.enc.stroke);

    // LayerNorm badge
    const normY = inY + MAT_H/2 + ROW_GAP;
    drawBadge(gL, CX, normY, 'LayerNorm', lc.fill, COLORS.norm.stroke);
    arrowDown(gL, CX, inY + MAT_H/2, normY - 17, lc.stroke);
    lbl(gL, CX + 70, normY, 'γ, β params', { size: 8, color: COLORS.muted, anchor: 'start' });

    // Normalized output
    const normOutY = normY + 17 + ROW_GAP/2 + MAT_H/2;
    arrowDown(gL, CX, normY + 17, normOutY - MAT_H/2, lc.stroke);
    drawSeqMatrix(gL, CX - 200, normOutY, 'x_norm', `[${nFrames}, ${dModel}]`, lc.fill, COLORS.norm.stroke, 170, MAT_H);

    // FFN: Linear up (W_a)
    const wAY = normOutY;
    drawWeight(gL, CX + 160, wAY, `W_${layer}a`, `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 130, WEIGHT_H);
    // matmul symbol
    opCircle(gL, CX + 10, wAY, '×', lc.stroke);
    drawArrow(gL as Sel, CX - 200 + 85 + 4, wAY, CX + 10 - 20, wAY, { color: lc.stroke });
    drawArrow(gL as Sel, CX + 10 + 20, wAY, CX + 160 - 65 - 4, wAY, { color: lc.stroke });

    // Linear up output
    const luOutY = wAY + WEIGHT_H/2 + ROW_GAP/2 + MAT_H/2;
    arrowDown(gL, CX + 10, wAY + 20, luOutY - MAT_H/2, lc.stroke);
    drawSeqMatrix(gL, CX, luOutY, `ffn_up`, `[${nFrames}, ${dModel}]`, lc.fill, lc.stroke, 170, 60);

    // GELU activation
    const geluY = luOutY + 30 + ROW_GAP/2;
    drawBadge(gL, CX, geluY, 'GELU', lc.fill, lc.stroke);
    arrowDown(gL, CX, luOutY + 30, geluY - 17, lc.stroke);

    // Linear down (W_b)
    const ldY = geluY + 17 + ROW_GAP/2 + WEIGHT_H/2;
    drawWeight(gL, CX + 140, ldY, `W_${layer}b`, `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 130, WEIGHT_H);
    opCircle(gL, CX - 30, ldY, '×', lc.stroke);
    drawArrow(gL as Sel, CX, geluY + 17, CX - 30, ldY - 40, { color: lc.stroke });
    drawArrow(gL as Sel, CX - 30 + 20, ldY, CX + 140 - 65 - 4, ldY, { color: lc.stroke });

    // FFN output
    const ffnOutY = ldY + WEIGHT_H/2 + ROW_GAP/2 + MAT_H/2;
    arrowDown(gL, CX + 140, ldY + WEIGHT_H/2, ffnOutY - MAT_H/2, lc.stroke);
    drawSeqMatrix(gL, CX, ffnOutY, 'ffn_out', `[${nFrames}, ${dModel}]`, lc.fill, lc.stroke, 170, 60);

    // Residual add
    const resY = ffnOutY + 30 + ROW_GAP/2;
    opCircle(gL, CX, resY, '⊕', lc.stroke);
    arrowDown(gL, CX, ffnOutY + 30, resY - 20, lc.stroke);
    lbl(gL, CX - 60, resY, 'residual', { size: 8.5, color: COLORS.muted, anchor: 'start' });

    // Dashed residual skip path from input to add
    const resStartY = inY;
    const resPathX = CX + 340;
    gL.append('path')
      .attr('d', `M${CX + 100},${resStartY} L${resPathX},${resStartY} L${resPathX},${resY} L${CX + 20},${resY}`)
      .attr('fill', 'none').attr('stroke', COLORS.wave.stroke).attr('stroke-width', 1.5).attr('stroke-dasharray', '6,3').attr('opacity', 0.6);
    lbl(gL, resPathX + 8, (resStartY + resY) / 2, 'skip', { size: 7.5, color: COLORS.wave.stroke, anchor: 'start' });

    // Layer output
    const outY = resY + 20 + ROW_GAP + MAT_H/2;
    const outLabel = layer === 1 ? 'audio_features' : `h_${layer}`;
    arrowDown(gL, CX, resY + 20, outY - MAT_H/2, lc.stroke);
    drawSeqMatrix(gL, CX, outY, outLabel, `[${nFrames}, ${dModel}]`, lc.fill, lc.stroke);
    drawShapeEq(gL, CX, outY + MAT_H/2 + 24, `x + W_${layer}b(GELU(W_${layer}a(LN(x)))) → [${nFrames}, ${dModel}]`, lc.stroke);

    steps.push(makeStep(stepId, `TF${layer + 1}`, `Transformer Layer ${layer + 1}`, `h = x + FFN(LN(x))`, `Pre-norm transformer layer with multi-head self-attention and FFN.`, `step-tf-${layer}`, lc.stroke, lc.fill));
    stepId++; y = outY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 8: Output ───────────────────────────────────────────────────────
  const gOut = startGroup(g, 'step-out', stepId);
  const hOut = stepHeader(gOut, CX, y, stepId, 'Output', `audio_features: [${nFrames}, ${dModel}]`, COLORS.wave.fill, COLORS.wave.stroke);
  arrowDown(gOut, CX, y, hOut, COLORS.wave.stroke);
  const finalY = hOut + BOX_TO_ROW + MAT_H/2;
  drawSeqMatrix(gOut, CX, finalY, 'output', `[${nFrames}, ${dModel}]`, COLORS.wave.fill, COLORS.wave.stroke, 240, MAT_H);
  arrowDown(gOut, CX, hOut, finalY - MAT_H/2, COLORS.wave.stroke);
  lbl(gOut, CX, finalY + MAT_H/2 + 18, `${nFrames} frames × ${dModel} dimensions`, { size: 9.5, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Output', 'Audio Features', `[${nFrames}, ${dModel}]`, 'Final audio feature representations.', 'step-out', COLORS.wave.stroke, COLORS.wave.fill));
  y = finalY + MAT_H/2 + 48;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Generic variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderGeneric(g: Gsel, startY: number, dModel: number, seqLen: number): { steps: AudioStep[]; y: number } {
  const steps: AudioStep[] = [];
  let stepId = 1;
  let y = startY;
  const T = seqLen;
  const nFft = 400;
  const nFrames = Math.ceil(T * 2 / nFft);
  const poolFrames = Math.ceil(nFrames / 4);

  // ── Step 1: Raw Waveform ─────────────────────────────────────────────────
  const g1 = startGroup(g, 'step-wave', stepId);
  const h1 = stepHeader(g1, CX, y, stepId, 'Raw Waveform', `wave: [${T}]`, COLORS.wave.fill, COLORS.wave.stroke);
  arrowDown(g1, CX, y, h1, COLORS.wave.stroke);
  const waveY = h1 + BOX_TO_ROW + WAVE_H / 2;
  drawWaveform(g1, CX, waveY, COLORS.wave.stroke);
  lbl(g1, CX, waveY + WAVE_H / 2 + 18, `${T} samples at 16 kHz`, { size: 9, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Input', 'Raw Waveform', `wave: [${T}]`, `Raw audio waveform with ${T} samples.`, 'step-wave', COLORS.wave.stroke, COLORS.wave.fill));
  stepId++; y = waveY + WAVE_H / 2 + STEP_GAP;

  // ── Step 2: STFT ─────────────────────────────────────────────────────────
  const g2 = startGroup(g, 'step-stft', stepId);
  const h2 = stepHeader(g2, CX, y, stepId, 'STFT', `|STFT(wave)|² → [${nFrames}, ${nFft/2}]`, COLORS.freq.fill, COLORS.freq.stroke);
  arrowDown(g2, CX, y, h2, COLORS.freq.stroke);
  const stftY = h2 + BOX_TO_ROW + SPEC_H / 2;
  drawSpectrogram(g2, CX, stftY, COLORS.freq.stroke, SPEC_W, SPEC_H);
  lbl(g2, CX, stftY - SPEC_H/2 - 10, 'power spectrogram', { size: 8.5, color: COLORS.muted });
  drawShapeEq(g2, CX, stftY + SPEC_H/2 + 28, `wave [${T}] → STFT(n_fft=${nFft}) → power [${nFrames}, ${nFft/2}]`, COLORS.freq.stroke);
  steps.push(makeStep(stepId, 'STFT', 'STFT', `|STFT(wave)|²`, 'Compute power spectrogram via short-time Fourier transform.', 'step-stft', COLORS.freq.stroke, COLORS.freq.fill));
  stepId++; y = stftY + SPEC_H/2 + 28 + STEP_GAP;

  // ── Step 3: Temporal Pooling ─────────────────────────────────────────────
  const g3 = startGroup(g, 'step-pool', stepId);
  const h3 = stepHeader(g3, CX, y, stepId, 'Temporal Pooling', `[${nFrames},·] → [${poolFrames},·] (stride 4)`, COLORS.mel.fill, COLORS.mel.stroke);
  arrowDown(g3, CX, y, h3, COLORS.mel.stroke);

  // Input frames (dense)
  const poolVisY = h3 + BOX_TO_ROW;
  const poolW = 320; const poolH = 56;
  const inG = g3.append('g').attr('transform', `translate(${CX - poolW/2}, ${poolVisY})`);
  inG.append('rect').attr('width', poolW).attr('height', poolH).attr('rx', 4).attr('fill', COLORS.freq.fill).attr('stroke', COLORS.freq.stroke).attr('stroke-width', 0.8);
  for (let i = 0; i < 24; i++) {
    const bw = poolW / 24 - 1;
    const bh = poolH * (0.3 + Math.abs(Math.sin(i * 0.5)) * 0.5);
    inG.append('rect').attr('x', i * (bw + 1) + 1).attr('y', poolH - bh).attr('width', bw).attr('height', bh).attr('rx', 1).attr('fill', COLORS.freq.stroke).attr('opacity', 0.4);
  }
  lbl(g3, CX, poolVisY - 10, `input: ${nFrames} frames`, { size: 8.5, color: COLORS.muted });

  // Pooling badge + arrow
  const poolBadgeY = poolVisY + poolH + ROW_GAP/2;
  drawBadge(g3, CX, poolBadgeY, 'avg pool (stride 4)', COLORS.mel.fill, COLORS.mel.stroke);
  arrowDown(g3, CX, poolVisY + poolH, poolBadgeY - 17, COLORS.mel.stroke);

  // Output frames (sparse)
  const outPoolY = poolBadgeY + 17 + ROW_GAP/2;
  const outG = g3.append('g').attr('transform', `translate(${CX - poolW/2}, ${outPoolY})`);
  outG.append('rect').attr('width', poolW).attr('height', poolH).attr('rx', 4).attr('fill', COLORS.mel.fill).attr('stroke', COLORS.mel.stroke).attr('stroke-width', 0.8);
  for (let i = 0; i < 6; i++) {
    const bw = poolW / 6 - 2;
    const bh = poolH * (0.3 + Math.abs(Math.sin(i * 0.8)) * 0.5);
    outG.append('rect').attr('x', i * (bw + 2) + 2).attr('y', poolH - bh).attr('width', bw).attr('height', bh).attr('rx', 1).attr('fill', COLORS.mel.stroke).attr('opacity', 0.4);
  }
  lbl(g3, CX, outPoolY + poolH + 16, `output: ${poolFrames} frames (4× shorter)`, { size: 8.5, color: COLORS.muted });
  drawShapeEq(g3, CX, outPoolY + poolH + 40, `avg_pool(kernel=4, stride=4): [${nFrames}, ${nFft/2}] → [${poolFrames}, ${nFft/2}]`, COLORS.mel.stroke);
  steps.push(makeStep(stepId, 'Pool', 'Temporal Pooling', `avg_pool(stride=4)`, 'Downsample time dimension by 4× via average pooling.', 'step-pool', COLORS.mel.stroke, COLORS.mel.fill));
  stepId++; y = outPoolY + poolH + 40 + STEP_GAP;

  // ── Step 4: Linear Projection ────────────────────────────────────────────
  const g4 = startGroup(g, 'step-proj', stepId);
  const h4 = stepHeader(g4, CX, y, stepId, 'Linear Projection', `h = pool · W_proj`, COLORS.enc.fill, COLORS.enc.stroke);
  arrowDown(g4, CX, y, h4, COLORS.enc.stroke);

  // Input pooled matrix
  const projRowY = h4 + BOX_TO_ROW + MAT_H/2;
  drawSeqMatrix(g4, CX - 200, projRowY, 'pooled', `[${poolFrames}, ${nFft/2}]`, COLORS.mel.fill, COLORS.mel.stroke, 170, MAT_H);

  // Matmul symbol
  opCircle(g4, CX - 30, projRowY, '×', COLORS.enc.stroke);
  drawArrow(g4 as Sel, CX - 200 + 85 + 4, projRowY, CX - 30 - 20, projRowY, { color: COLORS.enc.stroke });

  // Weight matrix
  drawWeight(g4, CX + 140, projRowY, 'W_proj', `[${nFft/2}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, WEIGHT_W, WEIGHT_H);
  drawArrow(g4 as Sel, CX - 30 + 20, projRowY, CX + 140 - WEIGHT_W/2 - 4, projRowY, { color: COLORS.enc.stroke });

  // Output
  const projOutY = projRowY + MAT_H/2 + ROW_GAP + MAT_H/2;
  arrowDown(g4, CX, projRowY + MAT_H/2, projOutY - MAT_H/2, COLORS.enc.stroke);
  drawSeqMatrix(g4, CX, projOutY, 'audio_features', `[${poolFrames}, ${dModel}]`, COLORS.enc.fill, COLORS.enc.stroke);
  drawShapeEq(g4, CX, projOutY + MAT_H/2 + 24, `pooled [${poolFrames}, ${nFft/2}] · W_proj [${nFft/2}, ${dModel}] → [${poolFrames}, ${dModel}]`, COLORS.enc.stroke);
  steps.push(makeStep(stepId, 'Project', 'Linear Projection', `h = pool · W_proj`, 'Project pooled features to model dimension.', 'step-proj', COLORS.enc.stroke, COLORS.enc.fill));
  stepId++; y = projOutY + MAT_H/2 + 24 + STEP_GAP;

  // ── Step 5: Output ───────────────────────────────────────────────────────
  const gOut = startGroup(g, 'step-out', stepId);
  const hOut = stepHeader(gOut, CX, y, stepId, 'Output', `audio: [${poolFrames}, ${dModel}]`, COLORS.wave.fill, COLORS.wave.stroke);
  arrowDown(gOut, CX, y, hOut, COLORS.wave.stroke);
  const finalY = hOut + BOX_TO_ROW + MAT_H/2;
  drawSeqMatrix(gOut, CX, finalY, 'output', `[${poolFrames}, ${dModel}]`, COLORS.wave.fill, COLORS.wave.stroke, 240, MAT_H);
  arrowDown(gOut, CX, hOut, finalY - MAT_H/2, COLORS.wave.stroke);
  lbl(gOut, CX, finalY + MAT_H/2 + 18, `${poolFrames} frames × ${dModel} dimensions`, { size: 9.5, color: COLORS.muted });
  steps.push(makeStep(stepId, 'Output', 'Audio Features', `[${poolFrames}, ${dModel}]`, 'Final audio feature representations.', 'step-out', COLORS.wave.stroke, COLORS.wave.fill));
  y = finalY + MAT_H/2 + 48;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderAudioEncoderDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const seqLen = Number(params.seq_len) || 1024;
  const variant = String(params.variant || 'whisper');

  const root = g as unknown as Gsel;
  let y = 28;

  lbl(root, CX, y, 'Audio Encoder', { size: 18, weight: '700', color: COLORS.text });
  y += 24;
  const variantLabel = variant === 'whisper' ? 'Whisper (Mel + Transformer)' : 'Generic (STFT + Linear)';
  lbl(root, CX, y, `${variantLabel} · d_model=${dModel} · seq_len=${seqLen}`, { size: 11, color: COLORS.muted });
  y += 32;

  y = drawParamSummary(root, CX, y, [`d_model=${dModel}`, `seq_len=${seqLen}`, `variant: ${variant}`]);
  y += 20;

  const result = variant === 'whisper' ? renderWhisper(root, y, dModel, seqLen) : renderGeneric(root, y, dModel, seqLen);

  let footerY = result.y + 24;

  const insightText = variant === 'whisper'
    ? 'Whisper processes audio through STFT → mel filterbank → log compression → positional encoding → transformer layers. The mel scale matches human frequency perception. Conv1d downsampling (stride=2) reduces temporal resolution before the transformer.'
    : 'Generic audio encoding uses STFT for frequency decomposition, temporal pooling (4× downsampling) to reduce sequence length, then a linear projection to the model dimension. Simpler but less expressive than transformer-based encoders.';

  const nFft = 400;
  const nFrames = Math.ceil(seqLen * 2 / nFft);
  const nMels = 128;

  const perfText = variant === 'whisper'
    ? `STFT: O(T · log(n_fft)). Mel filterbank: ${fmtNum(nFrames * nFft/2 * nMels)} ops. Transformer (2 layers): ${fmtNum(2 * (4 * dModel * dModel + 2 * nFrames * dModel * dModel))} FLOPs. Total encoder params: ~${fmtNum(2 * 4 * dModel * dModel + nMels * nFft/2)}.`
    : `STFT: O(T · log(n_fft)). Pool: O(${nFrames} · ${nFft/2}). Linear projection: ${fmtNum(Math.ceil(nFrames/4) * nFft/2 * dModel)} FLOPs. Params: ${fmtNum(nFft/2 * dModel)}.`;

  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 14;

  const codeLines = variant === 'whisper' ? [
    '# Whisper audio encoder',
    'mel = log_mel_spectrogram(audio, n_mels=128)  # [T, 128]',
    'x = F.gelu(conv1(mel))                         # feature mixing',
    'x = F.gelu(conv2(x))                            # 2× downsampling',
    'x = x + sinusoidal_positional_encoding',
    'for layer in transformer_layers:',
    '    x = x + FFN(LayerNorm(x))',
    'return x  # audio features [T/2, d_model]',
  ] : [
    '# Generic audio encoder',
    'stft = torch.stft(audio, n_fft=400, hop_length=100)',
    'power = stft.abs() ** 2                    # [T, n_fft/2]',
    'pooled = F.avg_pool1d(power, kernel_size=4, stride=4)',
    'audio_features = pooled @ W_proj           # [T/4, d_model]',
  ];

  footerY = drawCodeAnnotation(g, 80, footerY, W - 160, `Audio Encoder — ${variantLabel}`, [], codeLines);

  return { width: W, height: footerY + 24, steps: result.steps };
}
